// ==================== Interfaces ====================

export interface OfficialDoc {
  label: string;
  url: string;
}

export interface MenuItem {
  name: string;
  path: string;
  file: string;
  officialDocs?: OfficialDoc[];
  // Optional sub-heading inside a category's sidebar list. Items sharing a
  // group render under one label, in first-appearance order; ungrouped items
  // render first with no heading. Only DevOps uses this today.
  group?: string;
  // Index signature lets MenuItem flow into hooks that accept generic
  // `{ path: string; [key: string]: unknown }` shapes (e.g. ProgressItem).
  [key: string]: unknown;
}

export interface MenuSection {
  name: string;
  path?: string;
  file?: string;
  icon?: LucideIcon;
  gradient?: string;
  lightBg?: string;
  darkBg?: string;
  accent?: string;
  description?: string;
  items?: MenuItem[];
}

export interface CheatSheet {
  name: string;
  path: string;
  file: string;
  color: string;
  description: string;
}

export interface Question {
  id: string;
  question: string;
  answer: string;
  guide: string;
  type: 'output' | 'conceptual';
  difficulty?: string;
  // Index signature for compatibility with useSpacedRepetition's
  // `{ id: string; [key: string]: unknown }` shape.
  [key: string]: unknown;
}

export interface Heading {
  level: number;
  text: string;
  id: string;
}

// ==================== Data ====================

// LAZY, deliberately. NOTE: anything matched here still ships to visitors in
// plain text (just in a separate chunk) — never add private content to it.
// `private/` lives outside src/ and is gitignored; see AdminPage.tsx.
// This used to be `eager: true`, which inlined all 4.6 MB
// of markdown into the main chunk — about 90% of a 4.9 MB bundle — so every
// visitor downloaded all 68 guides in order to read one. Dropping `eager`
// makes each guide its own chunk, fetched when it is actually opened.
//
// Anything that needs data about every guide *before* one is opened (reading
// times on the home page, category totals, the related-guides strip) reads the
// precomputed `contentMeta` below instead. Anything that needs full text of
// everything (search, quiz, interview simulator) calls loadAllContent() on
// demand. Nothing should reach for the raw map directly.
const contentLoaders = import.meta.glob<string>(
  ['./content/**/*.md', '!./content/private/**'],
  { query: '?raw', import: 'default' },
);

/** Build-time metadata (reading time, size, question count) keyed by the same './content/…' paths. */
export const contentMeta: Record<string, { readMin: number; bytes: number; questions: number }> = contentMetaJson;

/** Precomputed reading time. Use this instead of estimateReadingTime() when you
 *  only have a file path and don't want to pull the markdown into the bundle. */
export function readMinFor(file: string): number {
  return contentMeta[file]?.readMin ?? 1;
}


const contentCache = new Map<string, string>();

// ---- in-flight tracking, so the UI can show real progress ----------------
// Content is fetched lazily, so a navigation can involve a network round trip
// with nothing on screen to explain the pause. These let a top-level progress
// indicator subscribe to actual pending fetches rather than guessing with a
// timer. Exposed as an external store for useSyncExternalStore.
let pendingLoads = 0;
const pendingListeners = new Set<() => void>();

function setPending(delta: number): void {
  pendingLoads += delta;
  pendingListeners.forEach(listener => listener());
}

export function subscribePendingLoads(listener: () => void): () => void {
  pendingListeners.add(listener);
  return () => { pendingListeners.delete(listener); };
}

export function getPendingLoads(): number {
  return pendingLoads;
}

/** Synchronous peek at the cache. Lets a component initialise from an already
 *  loaded guide instead of rendering a skeleton for one frame on every
 *  revisit — loadContent is async even on a cache hit, so without this a
 *  cached guide still flashes its loading state. */
export function peekContent(file: string): string | undefined {
  return contentCache.get(file);
}

/** Load one guide's markdown. Cached, so re-visiting a guide is instant. */
export async function loadContent(file: string): Promise<string> {
  const cached = contentCache.get(file);
  if (cached !== undefined) return cached;      // no fetch, no progress bar
  const loader = contentLoaders[file];
  if (!loader) return '';
  setPending(1);
  try {
    const text = await loader();
    contentCache.set(file, text);
    return text;
  } finally {
    setPending(-1);
  }
}

let allContentPromise: Promise<Record<string, string>> | null = null;

/** Load every guide's markdown. Only for features that genuinely need the full
 *  corpus — search, quiz, interview simulator. The promise is memoised so the
 *  second caller reuses the first download. */
export function loadAllContent(): Promise<Record<string, string>> {
  if (!allContentPromise) {
    allContentPromise = (async () => {
      const entries = await Promise.all(
        Object.keys(contentLoaders).map(async (file) => [file, await loadContent(file)] as const),
      );
      return Object.fromEntries(entries);
    })();
  }
  return allContentPromise;
}

