// ==================== Utilities ====================


/**
 * How many questions the corpus holds — WITHOUT downloading it.
 *
 * Summed over `menuStructure` exactly as `getAllQuestions()` iterates, so the
 * two agree by construction; `src/data.test.ts` pins that they do.
 *
 * This exists because the sidebar's Daily Review badge used to call
 * `getAllQuestions()`, which loads every guide — Lighthouse caught it pulling
 * **64 chunks, 1.6 MB, at High priority** on the *home page*, where none of
 * that text is ever shown. `requestIdleCallback` deferred when it started but
 * not how much it fetched, so on a throttled connection it saturated the
 * network and pushed simulated LCP to 12.8 s. `getDueCount` only ever reads
 * `q.id`, so a total is all the badge needed.
 */
export const totalQuestionCount: number = menuStructure
  .flatMap((section) => section.items ?? [])
  .reduce((n, item) => n + (contentMeta[item.file]?.questions ?? 0), 0);

export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

export function getTextContent(children: ReactNode): string {
  if (typeof children === 'string') return children;
  if (typeof children === 'number') return String(children);
  if (Array.isArray(children)) return children.map(getTextContent).join('');
  if (isValidElement(children) && children.props) {
    return getTextContent((children.props as { children?: ReactNode }).children);
  }
  return '';
}

export function extractHeadings(markdown: string): Heading[] {
  const headings: Heading[] = [];
  const regex = /^(#{2,4})\s+(.+)$/gm;
  let match: RegExpExecArray | null;
  while ((match = regex.exec(markdown)) !== null) {
    const raw = match[2]
      .replace(/\*\*/g, '')
      .replace(/`/g, '')
      .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
      .trim();
    headings.push({
      level: match[1].length,
      text: raw,
      id: slugify(raw),
    });
  }
  return headings;
}

export function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// ==================== Reading Time ====================

export function estimateReadingTime(markdown: string): number {
  if (!markdown) return 1;
  // Separate code blocks from prose
  let codeWords = 0;
  const proseOnly = markdown.replace(/```[\s\S]*?```/g, (match) => {
    codeWords += match.split(/\s+/).length;
    return '';
  });
  // Strip markdown syntax
  const cleaned = proseOnly
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\*\*|__|~~|`/g, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/!\[.*?\]\(.*?\)/g, '');
  const proseWords = cleaned.split(/\s+/).filter(Boolean).length;
  // Prose at 200 wpm, code at 100 wpm
  const minutes = Math.ceil((proseWords / 200) + (codeWords / 100));
  return Math.max(1, minutes);
}

// Question parsing lives in ./data/extractQuestions. Imported for
// getAllQuestions below, and re-exported so existing consumers keep importing
// it from `data`.
import { extractQuestions } from './data/extractQuestions';
export { extractQuestions };


/** Async because content is lazy-loaded (see contentLoaders above). Callers
 *  are Quiz and the Interview Simulator, both of which already have a loading
 *  state, so the download happens only when someone opens those features. */
export async function getAllQuestions(): Promise<Question[]> {
  const all = await loadAllContent();
  const questions: Question[] = [];
  for (const section of menuStructure) {
    if (!section.items) continue;
    for (const item of section.items) {
      const qs = extractQuestions(all[item.file] || '', item.name);
      questions.push(...qs);
    }
  }
  return questions;
}


